"""================================================================================                        PROJETO IOTEC - ENTERPRISE              GERADOR DE FATURA TESTE DE PRIMEIRA VENDA (R$ 29,90)================================================================================ Objetivo : Emitir uma fatura oficial do circuito de vendas IOTEC para validar            a baixa de pagamento, integração de log e fechamento do ciclo.================================================================================"""import osimport sysimport jsonimport uuidfrom datetime import datetimefrom dotenv import load_dotenv# Carrega variáveis de ambienteload_dotenv(override=True)def generate_first_sale_invoice(value=29.90, customer_name="Cliente Validação IOTEC"):    order_id = f"IOTEC-INV-{uuid.uuid4().hex[:8].upper()}"    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")        pix_key = os.getenv("PICPAY_PIX_KEY", "CNPJ_OU_CHAVE_NAO_CONFIGURADA")    paypal_id = os.getenv("PAYPAL_CLIENT_ID", "MODO_SANDBOX_OU_NAO_CONFIGURADO")        invoice_data = {        "invoice_id": order_id,        "date": timestamp,        "amount_brl": value,        "description": "Licença/Ativação Módulo Enterprise IOTEC - Primeira Venda",        "customer": customer_name,        "status": "PENDING_PAYMENT",        "payment_methods": {            "picpay_pix": pix_key,            "paypal_status": "ENABLED" if paypal_id != "MODO_SANDBOX_OU_NAO_CONFIGURADO" else "MANUAL_CHECKOUT"        }    }        # Salva o registro da fatura no histórico para auditagem do 019_IOTEC_PAYMENT_AUDITOR    log_dir = os.path.join(os.getcwd(), "logs")    os.makedirs(log_dir, exist_ok=True)        log_file = os.path.join(log_dir, "first_sale_records.json")        records = []    if os.path.exists(log_file):        try:            with open(log_file, "r", encoding="utf-8") as f:                records = json.load(f)        except Exception:            records = []                records.append(invoice_data)        with open(log_file, "w", encoding="utf-8") as f:        json.dump(records, f, indent=4, ensure_ascii=False)            return invoice_datadef display_invoice(inv):    print("\n" + "=" * 65)    print("           IOTEC ENTERPRISE - FATURA DE PRIMEIRA VENDA")    print("=" * 65)    print(f" ID DA FATURA : {inv['invoice_id']}")    print(f" DATA/HORA    : {inv['date']}")    print(f" CLIENTE      : {inv['customer']}")    print(f" DESCRIÇÃO    : {inv['description']}")    print(f" VALOR TOTAL  : R$ {inv['amount_brl']:.2f}")    print("-" * 65)    print(" DADOS PARA PAGAMENTO E VALIDAÇÃO DO CIRCUITO:")    print(f"   • PIX PicPay CNPJ : {inv['payment_methods']['picpay_pix']}")    print(f"   • Status PayPal   : {inv['payment_methods']['paypal_status']}")    print("-" * 65)    print(" [ INSTRUÇÃO ]: Realize o pagamento de R$ 29,90 usando os dados acima.")    print(" Em seguida, execute 'python 019_IOTEC_PAYMENT_AUDITOR.py' para dar")    print(" a baixa e fechar a validação do circuito técnico!")    print("=" * 65 + "\n")if __name__ == "__main__":    invoice = generate_first_sale_invoice()    display_invoice(invoice)